<?php
namespace Src\Pago\Infrastructure\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;use Src\OrdenTrabajo\Infrastructure\Models\OrdenTrabajoEloquentModel;
class PagoEloquentModel extends Model{use HasUuids;protected $table='pagos';protected $hidden=['idempotencia_clave','solicitud_hash'];protected $fillable=['numero','orden_id','factura_id','idempotencia_clave','solicitud_hash','monto','moneda','metodo','referencia','comprobante_numero','observaciones','estado','pagado_en','registrado_por','factura_numero_snapshot','orden_numero_snapshot','cliente_tipo_documento_snapshot','cliente_documento_snapshot','cliente_nombre_snapshot','vehiculo_placa_snapshot','vehiculo_descripcion_snapshot','servicios_snapshot','repuestos_snapshot','descuento_snapshot','impuesto_snapshot','detalle_snapshot','total_orden_snapshot','pagado_acumulado_snapshot','saldo_resultante_snapshot','anulado_en','anulado_por','motivo_anulacion','reembolsado_en','reembolsado_por','motivo_reembolso'];protected function casts():array{return['monto'=>'decimal:2','servicios_snapshot'=>'decimal:2','repuestos_snapshot'=>'decimal:2','descuento_snapshot'=>'decimal:2','impuesto_snapshot'=>'decimal:2','detalle_snapshot'=>'array','total_orden_snapshot'=>'decimal:2','pagado_acumulado_snapshot'=>'decimal:2','saldo_resultante_snapshot'=>'decimal:2','pagado_en'=>'immutable_datetime','anulado_en'=>'immutable_datetime','reembolsado_en'=>'immutable_datetime'];}public function orden():BelongsTo{return$this->belongsTo(OrdenTrabajoEloquentModel::class,'orden_id');}public function factura():BelongsTo{return$this->belongsTo(\Src\Facturacion\Infrastructure\Models\FacturaOrdenEloquentModel::class,'factura_id');}public function historial():HasMany{return$this->hasMany(PagoHistorialEloquentModel::class,'pago_id');}public function movimientos():HasMany{return$this->hasMany(PagoMovimientoEloquentModel::class,'pago_id');}}
